{
  "sql": "SELECT Name FROM visitor WHERE Level_of_membership > 4 ORDER BY Level_of_membership DESC"
}

{
  "sql": "SELECT Name, Level_of_membership FROM visitor WHERE Level_of_membership > 4 ORDER BY Age DESC"
}

{
  "sql": "SELECT Museum_ID, Name FROM museum ORDER BY Num_of_Staff DESC LIMIT 1"
}

{
  "sql": "SELECT Open_Year, Num_of_Staff FROM museum WHERE Name = 'Plaza Museum'"
}

{
  "sql": "SELECT Name FROM museum WHERE Num_of_Staff > (SELECT MIN(Num_of_Staff) FROM museum WHERE Open_Year > '2010')"
}

{
  "sql": "SELECT v.ID, v.Name, v.Age FROM visitor v JOIN visit vi ON v.ID = vi.visitor_ID GROUP BY v.ID, v.Name, v.Age, vi.Museum_ID HAVING COUNT(*) > 1"
}

{
  "sql": "SELECT v.ID, v.Name, v.Level_of_membership FROM visitor v JOIN visit vi ON v.ID = vi.visitor_ID GROUP BY v.ID, v.Name, v.Level_of_membership ORDER BY SUM(vi.Total_spent) DESC LIMIT 1"
}

{
  "sql": "SELECT m.Museum_ID, m.Name FROM museum m JOIN visit v ON m.Museum_ID = v.Museum_ID GROUP BY m.Museum_ID, m.Name ORDER BY COUNT(*) DESC LIMIT 1"
}

{
  "sql": "SELECT Name FROM museum WHERE Museum_ID NOT IN (SELECT DISTINCT Museum_ID FROM visit)"
}

{
  "sql": "SELECT v.Name, v.Age FROM visitor v JOIN visit vi ON v.ID = vi.visitor_ID ORDER BY vi.Num_of_Ticket DESC LIMIT 1"
}

{
  "sql": "SELECT SUM(vi.Total_spent) FROM visit vi JOIN visitor v ON vi.visitor_ID = v.ID WHERE v.Level_of_membership = 1"
}

{
  "sql": "SELECT v.Name FROM visitor v WHERE v.ID IN (SELECT vi1.visitor_ID FROM visit vi1 JOIN museum m1 ON vi1.Museum_ID = m1.Museum_ID WHERE m1.Open_Year < '2009') AND v.ID IN (SELECT vi2.visitor_ID FROM visit vi2 JOIN museum m2 ON vi2.Museum_ID = m2.Museum_ID WHERE m2.Open_Year > '2011')"
}

{
  "sql": "SELECT COUNT(*) FROM visitor WHERE ID NOT IN (SELECT vi.visitor_ID FROM visit vi JOIN museum m ON vi.Museum_ID = m.Museum_ID WHERE m.Open_Year > '2010')"
}

{
  "sql": "SELECT COUNT(*) FROM museum WHERE Open_Year > '2013' OR Open_Year < '2008'"
}
